create or replace function public.s7_get_teacher_console(
  p_room_code text,p_teacher_token text
) returns jsonb language plpgsql security definer set search_path=public as $$
declare
  r text:=upper(trim(p_room_code));g public.game_runs%rowtype;s public.s3_runtime_scene_state%rowtype;
  s5 public.s5_run_state%rowtype;s6 public.s6_run_state%rowtype;d public.discussion_sessions%rowtype;
  act_no int;players jsonb;transcript jsonb;pockets jsonb;group_items jsonb;events jsonb;
  phase_validity jsonb;interventions jsonb;audio jsonb;filename text;
begin
  perform public.s1_assert_teacher(r,p_teacher_token);
  select * into g from public.game_runs where room_code=r and status='active';
  if not found then return jsonb_build_object('active',false);end if;
  select * into s from public.s3_runtime_scene_state where run_id=g.run_id;
  select * into s6 from public.s6_run_state where run_id=g.run_id;
  if found then act_no:=s6.act_no;else select * into s5 from public.s5_run_state where run_id=g.run_id;end if;
  if act_no is null and s5.run_id is not null then act_no:=s5.act_no;end if;
  if act_no is null then act_no:=nullif(substring(coalesce(s.scene_id,g.scene_id) from 'act([0-9]+)'),'')::int;end if;
  select * into d from public.discussion_sessions where run_id=g.run_id order by started_at desc limit 1;
  filename:=to_char(g.run_started_at at time zone 'UTC','YYYY-MM-DD_HH24-MI-SS')||'_'||g.run_id||case when g.run_mode='audit'then'_audit'else''end||'.json';

  select coalesce(jsonb_agg(jsonb_build_object(
    'player_id',p.player_id,'display_name',p.display_name,'role_slot',p.role_slot,
    'online',p.last_seen_at>clock_timestamp()-interval '30 seconds','player_location',pp.player_location,
    'submitted',exists(select 1 from public.runtime_player_decisions x where x.run_id=g.run_id and x.player_id=p.player_id and x.phase_key=coalesce(s.phase_key,g.phase_key))
      or (s.phase_key='private_first_action' and pp.act1_choice_id is not null)
      or (s.phase_key='private_first_meeting' and pp.first_meeting_choice is not null)
      or (s.phase_key='private_route_choice' and pp.act4_choice_id is not null)
      or exists(select 1 from public.s5_votes x where x.run_id=g.run_id and x.player_id=p.player_id and x.phase_key=coalesce(s5.phase_key,s.phase_key))
      or (coalesce(s5.phase_key,'')='act8_private' and exists(select 1 from public.s5_act8_private_choices x where x.run_id=g.run_id and x.player_id=p.player_id))
      or exists(select 1 from public.s6_choices x where x.run_id=g.run_id and x.player_id=p.player_id and x.phase_key=s6.phase_key and x.round_no=s6.round_no)
      or (s6.phase_key='act11_allocation' and exists(select 1 from public.s6_allocations x where x.run_id=g.run_id and x.player_id=p.player_id))
      or (s6.phase_key='act12_tasks' and exists(select 1 from public.s6_station_tasks x where x.run_id=g.run_id and x.player_id=p.player_id)),
    'locked_choice_value',case coalesce(s.phase_key,g.phase_key)
      when'private_first_action'then pp.act1_choice_id when'private_first_meeting'then pp.first_meeting_choice
      when'private_route_choice'then pp.act4_choice_id when'act8_private'then(select x.choice_id from public.s5_act8_private_choices x where x.run_id=g.run_id and x.player_id=p.player_id)
      when'act10_private'then(select x.choice_id from public.s6_choices x where x.run_id=g.run_id and x.player_id=p.player_id and x.phase_key='act10_private' order by x.round_no desc limit 1) end,
    'locked_choice_state',case when case coalesce(s.phase_key,g.phase_key)
      when'private_first_action'then pp.act1_choice_id when'private_first_meeting'then pp.first_meeting_choice
      when'private_route_choice'then pp.act4_choice_id when'act8_private'then(select x.choice_id from public.s5_act8_private_choices x where x.run_id=g.run_id and x.player_id=p.player_id)
      when'act10_private'then(select x.choice_id from public.s6_choices x where x.run_id=g.run_id and x.player_id=p.player_id and x.phase_key='act10_private' order by x.round_no desc limit 1) end is null
      then'WAITING'else'LOCKED / NOT YET REVEALED TO PLAYERS'end,
    'audit_debug',case when g.run_mode='audit'and g.audit_private_debug_view then jsonb_build_object('act1_choice',pp.act1_choice_id,'first_meeting_choice',pp.first_meeting_choice,'act4_choice',pp.act4_choice_id) end
  ) order by p.role_slot),'[]'::jsonb) into players
  from public.s1_room_players p left join public.s3b_player_progress pp on pp.run_id=g.run_id and pp.player_id=p.player_id where p.room_code=r;

  select coalesce(jsonb_agg(jsonb_build_object('display_name',p.display_name,'role_slot',p.role_slot,'message_text',m.message_text,'created_at',m.created_at) order by m.message_id),'[]') into transcript from public.dialogue_messages m join public.s1_room_players p using(player_id) where m.run_id=g.run_id;
  select coalesce(jsonb_agg(jsonb_build_object('player_id',p.player_id,'display_name',p.display_name,'role_slot',p.role_slot,'items',(select coalesce(jsonb_agg(jsonb_build_object('item_key',i.item_key,'acquired_at',i.acquired_at)order by i.acquired_at),'[]')from public.s3_player_items i where i.run_id=g.run_id and i.physical_owner_id=p.player_id),'observations',(select coalesce(jsonb_agg(jsonb_build_object('observation_key',o.observation_key,'display_text_key',o.display_text_key)order by o.discovered_at),'[]')from public.s3_player_observations o where o.run_id=g.run_id and o.player_id=p.player_id),'shared_photos',(select coalesce(jsonb_agg(jsonb_build_object('source_item_key',x.source_item_key,'source_view',x.source_view,'label_text_key',x.label_text_key)order by x.shared_at),'[]')from public.s3_shared_photos x where x.run_id=g.run_id and x.received_by=p.player_id))order by p.role_slot),'[]') into pockets from public.s1_room_players p where p.room_code=r;
  select coalesce(jsonb_agg(jsonb_build_object('item_key',item_key,'label_text_key',label_text_key,'acquired_at',acquired_at)order by acquired_at),'[]') into group_items from public.s3_group_items where run_id=g.run_id;
  select coalesce(jsonb_agg(jsonb_build_object('event_type',event_type,'scene_id',scene_id,'phase_key',phase_key,'validity',validity,'behavior_scoring',behavior_scoring,'details',details,'created_at',created_at)order by event_id desc),'[]') into events from(select*from public.runtime_events where run_id=g.run_id order by event_id desc limit 50)x;
  select coalesce(jsonb_agg(jsonb_build_object('scene_id',scene_id,'phase_key',phase_key,'step_key',step_key,'validity',validity,'event_count',n)order by scene_id,phase_key,step_key,validity),'[]') into phase_validity from(select coalesce(scene_id,'unscoped')scene_id,coalesce(phase_key,'unscoped')phase_key,coalesce(step_key,'unscoped')step_key,coalesce(validity,'unclassified')validity,count(*)n from public.runtime_events where run_id=g.run_id group by scene_id,phase_key,step_key,validity)x;
  select coalesce(jsonb_agg(jsonb_build_object('event_id',event_id,'event_type',event_type,'scene_id',scene_id,'phase_key',phase_key,'step_key',step_key,'details',details,'created_at',created_at)order by event_id),'[]') into interventions from public.runtime_events where run_id=g.run_id and(event_source='teacher_override'or event_type in('teacher_audit_private_debug_changed','teacher_session_released'));
  select jsonb_build_object('current_cue_key',s6.feedback_audio_key,'current_occurrence_id',s6.feedback_audio_occurrence_id,'recent',(select coalesce(jsonb_agg(jsonb_build_object('occurrence_id',o.occurrence_id,'cue_key',o.cue_key,'phase_key',o.phase_key,'triggered_at',o.triggered_at,'consumed_count',(select count(*)from public.s6_audio_consumptions c where c.occurrence_id=o.occurrence_id))order by o.triggered_at desc),'[]')from(select*from public.s6_audio_occurrences where run_id=g.run_id order by triggered_at desc limit 10)o))into audio;

  return jsonb_build_object('active',true,'run',jsonb_build_object('run_id',g.run_id,'run_mode',g.run_mode,'behavior_dataset_eligible',g.behavior_dataset_eligible,'status',g.status,'audit_private_debug_view',g.audit_private_debug_view),'current',jsonb_build_object('act_no',act_no,'scene_id',coalesce(s.scene_id,g.scene_id),'phase_key',coalesce(s.phase_key,g.phase_key),'step_key',coalesce(s.step_key,g.step_key),'display_mode',s.display_mode,'text_key',s.text_key,'current_route',coalesce(s.current_route_target,(select group_route from public.s3b_run_state where run_id=g.run_id)),'wayfinding_target',s.wayfinding_target),'countdown',case when d.discussion_session_id is null then null else jsonb_build_object('status',d.status,'phase_deadline',d.phase_deadline,'remaining_seconds',greatest(0,extract(epoch from d.phase_deadline-clock_timestamp())::int))end,'players',players,'discussion',jsonb_build_object('discussion_session_id',d.discussion_session_id,'status',d.status,'topic',d.topic,'messages',transcript),'pockets',pockets,'group_items',group_items,'audio',audio,'events',events,'phase_behavior_validity',phase_validity,'teacher_interventions',interventions,'override_history',(select coalesce(jsonb_agg(to_jsonb(o)order by o.created_at desc),'[]')from public.teacher_overrides o where o.run_id=g.run_id),'export',jsonb_build_object('game_completed',false,'export_ready',false,'enabled',false,'filename_preview',filename));
end$$;

create or replace function public.s5_teacher_open_vote(p_room_code text,p_teacher_token text)returns jsonb language plpgsql security definer set search_path=public as $$
declare room text:=upper(trim(p_room_code));g public.game_runs%rowtype;s public.s5_run_state%rowtype;sid uuid;
begin perform public.s1_assert_teacher(room,p_teacher_token);g:=public.s2_get_active_run(room);select*into s from public.s5_run_state where run_id=g.run_id;select discussion_session_id into sid from public.s5_rounds where run_id=g.run_id and phase_key=s.phase_key and vote_round=s.vote_round;update public.discussion_sessions set status='voting',phase_deadline=now()+make_interval(secs=>vote_time_limit_sec)where discussion_session_id=sid and status='discussion';if not found then raise exception'Current Sprint 5 discussion is not open.';end if;
insert into public.runtime_events(run_id,room_code,discussion_session_id,event_type,details,scene_id,phase_key,step_key,event_source,validity,behavior_scoring,interaction_id)values(g.run_id,room,sid,'teacher_intervention_s5_vote_opened',jsonb_build_object('vote_round',s.vote_round),null,s.phase_key,null,'teacher_override','valid',false,sid);
return jsonb_build_object('ok',true,'discussion_session_id',sid);end$$;

create or replace function public.s5_teacher_add_time(p_room_code text,p_teacher_token text,p_seconds integer)returns jsonb language plpgsql security definer set search_path=public as $$
declare room text:=upper(trim(p_room_code));g public.game_runs%rowtype;s public.s5_run_state%rowtype;sid uuid;
begin if p_seconds<1 or p_seconds>600 then raise exception'Invalid time extension.';end if;perform public.s1_assert_teacher(room,p_teacher_token);g:=public.s2_get_active_run(room);select*into s from public.s5_run_state where run_id=g.run_id;select discussion_session_id into sid from public.s5_rounds where run_id=g.run_id and phase_key=s.phase_key and vote_round=s.vote_round;update public.discussion_sessions set phase_deadline=greatest(coalesce(phase_deadline,now()),now())+make_interval(secs=>p_seconds)where discussion_session_id=sid and status in('discussion','voting','waiting_for_missing_player');if not found then raise exception'Current Sprint 5 discussion cannot receive time.';end if;
insert into public.runtime_events(run_id,room_code,discussion_session_id,event_type,details,scene_id,phase_key,step_key,event_source,validity,behavior_scoring,interaction_id)values(g.run_id,room,sid,'teacher_intervention_s5_time_added',jsonb_build_object('seconds',p_seconds,'vote_round',s.vote_round),null,s.phase_key,null,'teacher_override','valid',false,sid);
return jsonb_build_object('ok',true,'discussion_session_id',sid);end$$;

create function public.s7_mirror_teacher_discussion_event() returns trigger
language plpgsql security definer set search_path=public as $$
begin
  if new.event_type in('vote_opened_by_teacher','teacher_added_time') then
    insert into public.runtime_events(run_id,room_code,discussion_session_id,event_type,details,scene_id,phase_key,step_key,event_source,validity,behavior_scoring,interaction_id)
    values(new.run_id,new.room_code,new.discussion_session_id,'teacher_intervention_'||new.event_type,
      new.details||jsonb_build_object('source_event_id',new.event_id),new.scene_id,new.phase_key,new.step_key,'teacher_override','valid',false,new.interaction_id);
  end if;
  return new;
end$$;

create or replace function public.s8_get_player_state(p_room_code text,p_session_token text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;f public.s8_finalizations%rowtype;
begin
 p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);
 if g.run_id is null then g:=public.s8_latest_completed_run(room);end if;
 if g.run_id is null then return jsonb_build_object('active',false);end if;
 select * into f from public.s8_finalizations where run_id=g.run_id;
 return jsonb_build_object('active',found,'run_id',g.run_id,'scene_id',case when found then'act14_final_reveal'end,'phase_key',case when found then'act14_complete'end,'text_keys',case when found then jsonb_build_array('act14.001','act14.002','act14.003','act14.004','act14.005')else'[]'::jsonb end,'session_integrity_verified',g.session_integrity_verified,'game_completed',g.game_completed,'export_ready',g.export_ready,'integrity_report',case when found then f.integrity_report end);
end$$;

create or replace function public.s8_capture_choice_step()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if new.phase_key='act9_console' and new.action_step is null then
    select act9_step into new.action_step from public.s6_run_state where run_id=new.run_id;
  end if;
  return new;
end$$;

create or replace function public.s8_integrity_obligation(
  p_present boolean,
  p_evidence_identity jsonb default null,
  p_missing_reason text default 'required_evidence_missing',
  p_not_applicable_reason text default null,
  p_override_run_id uuid default null,
  p_override_field text default null
) returns jsonb language plpgsql stable security definer set search_path=public as $$
begin
  if p_not_applicable_reason is not null then
    return jsonb_build_object('state','not_applicable','reason_code',p_not_applicable_reason);
  end if;
  if p_present then
    return jsonb_strip_nulls(jsonb_build_object('state','present','evidence_identity',p_evidence_identity));
  end if;
  if p_override_run_id is not null and p_override_field is not null and exists(
    select 1 from public.teacher_override_validity
    where run_id=p_override_run_id and semantic_field=p_override_field
      and validity='invalid_teacher_override'
  ) then
    return jsonb_build_object('state','invalid_teacher_override','reason_code','exact_governed_override','evidence_identity',p_override_field);
  end if;
  return jsonb_build_object('state','missing_technical_evidence','reason_code',p_missing_reason);
end$$;

create function public.s8_finalize(p_room_code text,p_session_token text,p_client_request_id uuid,p_expected_run_id uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare room text:=upper(trim(p_room_code)); p public.s1_room_players%rowtype; g public.game_runs%rowtype;
  f public.s8_finalizations%rowtype; report jsonb; schema_version text:='1.1';
begin
  if p_expected_run_id is null then raise exception 'EXPECTED_RUN_ID_REQUIRED'; end if;
  p:=public.s1_get_player_by_session(room,p_session_token);
  select * into g from public.game_runs where run_id=p_expected_run_id and room_code=room for update;
  if not found then raise exception 'FINALIZATION_RUN_ROOM_MISMATCH'; end if;
  select * into f from public.s8_finalizations where run_id=p_expected_run_id;
  if found then return jsonb_build_object('ok',true,'idempotent_replay',true,'run_id',p_expected_run_id,'export_schema_version',f.export_schema_version); end if;
  if g.status<>'active' or not exists(select 1 from public.game_runs where room_code=room and run_id=p_expected_run_id and status='active') then
    raise exception 'STALE_FINALIZATION_RUN';
  end if;
  perform public.s6_refresh_owned_discussion(p_expected_run_id); perform public.s6_tick_cinematic(p_expected_run_id);
  report:=public.s8_verify_integrity(p_expected_run_id);
  if not coalesce((report->>'verified')::boolean,false) then raise exception 'Session integrity verification failed.' using detail=report::text; end if;
  insert into public.s8_finalizations(run_id,finalized_by,client_request_id,integrity_report,export_schema_version)
  values(p_expected_run_id,p.player_id,p_client_request_id,report,schema_version) returning * into f;
  update public.s6_run_state set act_no=14,phase_key='act14_complete',updated_at=now() where run_id=p_expected_run_id;
  update public.game_runs set status='completed',scene_id='act14_final_reveal',phase_key='act14_complete',step_key='ending',session_integrity_verified=true,game_completed=true,export_ready=true,completed_at=now() where run_id=p_expected_run_id;
  insert into public.runtime_events(run_id,room_code,event_type,actor_player_id,details,scene_id,phase_key,step_key,event_source,validity,behavior_scoring,client_request_id)
  values(p_expected_run_id,room,'session_finalized',p.player_id,jsonb_build_object('integrity_report',report,'export_schema_version',f.export_schema_version),'act14_final_reveal','act14_complete','ending','player','valid',false,p_client_request_id);
  return jsonb_build_object('ok',true,'run_id',p_expected_run_id,'session_integrity_verified',true,'game_completed',true,'export_ready',true,'export_schema_version',f.export_schema_version);
end$$;
